-- Тема 14: правки по отчёту Codex (23 исправлений в 13 вопросах), ключи не меняются.
-- Источник: scripts/questions/095_codex_topic14_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', NULL, NULL, NULL, 'Что нужно подготовить заранее, чтобы восстановить базу данных из полного SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?'),
        ('option', 'Что нужно, чтобы pg_basebackup мог подключиться по протоколу репликации?', 'Роль с атрибутом REPLICATION', 'Роль с REPLICATION либо суперпользователь', 'Право подключаться по протоколу репликации; подходит и суперпользователь.', 'Право подключаться по протоколу репликации есть у таких ролей и у суперпользователя.'),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', '\copy читает файл на клиенте, COPY — файл на сервере', '\copy работает с файлом на клиенте, COPY — на сервере', NULL, NULL),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', 'COPY поддерживает формат CSV, а \copy — текстовый', 'COPY требует заголовок CSV, а \copy обходится без него', 'Обе поддерживают форматы text, csv и binary: \copy передаёт параметры команде COPY.', 'Заголовок в обеих командах задаёт параметр HEADER, по умолчанию его нет.'),
        ('option', 'Когда сегмент журнала попадает в файловый архив?', 'Когда сервер переключится на следующий сегмент', NULL, 'Сервер передаёт в архив заполненный сегмент после переключения на следующий, поэтому текущий сегмент в архив не попадает и возникают задержки.', 'Архивируется завершённый сегмент, а завершить его сервер может и до заполнения. Текущий сегмент в архив не попадает, отсюда задержки.'),
        ('option', 'Когда сегмент журнала попадает в файловый архив?', 'Сразу после записи каждой журнальной записи на диск', NULL, 'Так работает потоковый архив, а не файловый.', 'Так ведёт архив pg_receivewal: он принимает WAL, не дожидаясь конца сегмента. Файловый архив работает посегментно.'),
        ('explanation', 'Что нужно подготовить заранее, чтобы восстановить базу данных из полного SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', NULL, NULL, 'SQL-дамп без --create восстанавливают в заранее созданную пустую базу (рекомендуется из template0); также подготавливают используемые роли и табличные пространства. При восстановлении архивного формата через pg_restore есть и другие возможности: --create создаёт базу, а --no-owner и --no-tablespaces обходятся без ролей и пространств. После восстановления рекомендуется ANALYZE, поскольку дамп не содержит статистики планировщика.', 'SQL-дамп без --create восстанавливают в заранее созданную пустую базу (рекомендуется из template0); также подготавливают используемые роли и табличные пространства. При восстановлении архивного формата через pg_restore есть и другие возможности: --create создаёт базу, --no-owner не восстанавливает владельцев, --no-tablespaces — размещение по табличным пространствам; роли, которым выдаются права, всё равно нужны. После восстановления рекомендуется ANALYZE, поскольку дамп не содержит статистики планировщика.'),
        ('option', 'Что нужно подготовить заранее, чтобы восстановить базу данных из полного SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', 'Пустую базу данных (лучше из template0)', 'Пустую базу данных для восстановления', NULL, NULL),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Все записи, сделанные после последней базовой копии', 'Записи после базовой копии, включая заархивированные', NULL, NULL),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Записи незаполненного сегмента WAL, который не попал в архив', 'Записи текущего сегмента WAL, не попавшего в архив', NULL, NULL),
        ('explanation', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', NULL, NULL, 'Такой сегмент можно скопировать в каталог pg_wal вручную, если он ещё доступен. При сбоях архивации таких сегментов может оказаться несколько.', 'Такой сегмент можно скопировать в каталог pg_wal вручную, если он ещё доступен. При сбоях или отставании архивации теряться могут и завершённые сегменты, ещё не скопированные в архив.'),
        ('option', 'Что верно для физической резервной копии?', 'Восстановление выполняется быстрее, чем из логической копии', 'Индексы восстанавливаются из готовых файлов', 'Файлы копируются как есть, индексы строить не нужно.', 'Индексы не строятся заново; это обычно ускоряет восстановление, но итоговое время зависит и от объёма WAL.'),
        ('option', 'Что верно для физической резервной копии?', 'С архивом журналов можно восстановиться на нужный момент', NULL, 'Журналы применяются до целевой точки.', 'Журналы применяются до целевой точки. Она должна быть позже окончания базовой копии, а WAL до неё — непрерывным.'),
        ('option', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', 'Формат с оглавлением и параллельная работа (-j)', 'Формат directory и параллельная обработка', NULL, NULL),
        ('option', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', 'Выполнение скрипта в psql в нескольких сеансах', NULL, 'Простой SQL-скрипт выполняется последовательно.', 'psql выполняет скрипт в одном сеансе; запуск того же скрипта в нескольких сеансах выполнит команды повторно.'),
        ('option', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', 'Отключение журнала предзаписи на время загрузки', NULL, 'Это не штатный способ ускорения восстановления.', 'Это не средство параллельной работы. Объём WAL при загрузке уменьшают настройки (wal_level = minimal), а не отключение журнала.'),
        ('option', 'Какое преимущество у логической резервной копии?', 'Её можно восстановить на новой основной версии PostgreSQL', 'Её можно восстановить на новой версии PostgreSQL', 'Нужна только совместимость на уровне команд SQL, поэтому подходят и другая основная версия, и другая архитектура.', 'Нужна только совместимость на уровне команд SQL: дамп переносят на более новую основную версию и на другую архитектуру. Перенос на более старую версию не гарантируется.'),
        ('option', 'Какое ограничение у физической резервной копии?', 'Восстанавливается весь кластер, на той же основной версии', 'Восстановить можно на сервере той же основной версии', 'Нужна двоичная совместимость: та же основная версия и та же архитектура; отдельную базу из физической копии не восстановить.', 'Нужна двоичная совместимость: та же основная версия и та же архитектура. Восстанавливается весь кластер, отдельную базу не восстановить.'),
        ('option', 'Какое ограничение у физической резервной копии?', 'Восстановление идёт медленнее, чем из логической копии', NULL, 'Восстановление быстрое: файлы копируются как есть.', 'Объекты не создаются заново, поэтому восстановление обычно быстрее.'),
        ('option', 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', 'Журналы не нужны: горячая копия уже согласована', NULL, 'Так бывает только при копировании остановленного сервера.', 'Без журналов обходится лишь копия корректно остановленного сервера.'),
        ('option', 'Чем потоковый архив журналов, который ведёт pg_receivewal, отличается от файлового?', 'Записи попадают в архив сразу, не дожидаясь конца сегмента', 'Записи пишутся в архив по мере получения, до конца сегмента', NULL, NULL),
        ('option', 'Почему копия pg_basebackup с WAL называется автономной?', 'Для её восстановления журналы WAL не нужны вовсе', 'Для её восстановления журналы WAL не нужны', NULL, NULL),
        ('option', 'Что происходит, если archive_command завершилась с ненулевым статусом?', 'Сегмент остаётся в pg_wal, сервер повторяет попытку позже', 'Сегмент остаётся, архивация повторяется позже', 'Сегмент WAL не удаляется, попытки повторяются, пока команда не вернёт 0.', 'Сегмент WAL остаётся в pg_wal, попытки повторяются, пока команда не вернёт 0.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
